{
  "example_tasks": {
    "常识问答": [
      "想了解领养一种宠物前该怎么判断自己是否适合，并顺便知道需要承担哪些日常照护责任。",
      "路边发现一只看起来受伤的野生动物时，怎样判断它是否真的需要救助，以及最初应该避免做什么。",
      "领养、暂养和寄养分别有什么区别，想帮助动物但暂时不能长期饲养时该怎么选择。",
      "第一次去动物救助机构申请领养时，通常会关注哪些条件，领养人可以提前做哪些准备。",
      "为什么不能随意给野生动物投喂或把人工饲养的动物放生，遇到类似情况时应如何理解其中的生态风险。"
    ]
  }
}

{
  "episode_situation": "傍晚六点半，用户刚在居住小区一栋楼的入口旁发现一只不熟悉的流浪猫，此刻站在离绿篱约四米的位置观察。她平时会给小区里几只固定出现的流浪猫添水，因此能确认这只猫不是自己经常照看的那几只。十分钟前，她看到猫从步道缓慢挪到绿篱下，移动时明显少用左后腿，但没有看到持续流血或明显外露的伤口。猫目前保持清醒，能够自行躲避，用户一靠近到约三米处便会压低身体并发出警戒声，所以她已经退回楼门附近，没有尝试触碰或追赶。猫所在位置不在车道上，不过晚些时候可能会有住户牵狗经过，这让用户担心继续等待也并非毫无风险。用户家中有硬壳宠物箱、厚毛巾和一次性手套，但没有诱捕笼、动物用药或私家车，也不确定自己能否安全把猫装进箱子。她记得附近有一家安禾动物诊所，步行约十五分钟，但尚不清楚诊所是否接收流浪动物，也没有熟悉的救助组织联系人。她还没有给猫喂食或用药，只在远处观察，想先弄清哪些迹象意味着需要尽快联系专业人员，哪些情况可以保持距离继续监测。她尤其犹豫的是，临时带回家可能便于保暖和观察，却也可能造成抓咬、应激、传染隔离困难，甚至让仍有照护者的猫离开原活动范围。眼下需要结合这次经历比较临时照护、联系专业救助和暂不干预三类做法，并整理出以后可重复使用的判断顺序，同时保留对伤势严重程度、猫是否有主人以及本地机构能否接收等未决问题。",
  "task_reference_data": [
    "来自用户刚才约十分钟的现场观察：猫移动缓慢，明显少用左后腿，但仍能自行走到绿篱下；用户未看到持续流血、外露伤口或失去意识，伤情尚未经过专业检查。",
    "来自用户现场观察：用户接近到约三米时，猫会压低身体并发出警戒声；用户已经退回约四米外，尚未触碰、围堵或追赶它。",
    "来自用户对小区环境的了解：猫所在绿篱不在车道内，但住户偶尔会牵狗经过；这只猫不是用户平时固定照看的几只流浪猫，是否有主人或其他照护者尚未核实。",
    "来自用户家中现有物品的记忆：可用物品包括硬壳宠物箱、厚毛巾和一次性手套；没有诱捕笼、动物用药或私家车，用户也没有安全抓捕受伤猫的经验。",
    "来自用户记忆但尚未核实的信息：安禾动物诊所距离小区步行约十五分钟，用户不知道其是否接收流浪动物；目前没有熟悉的专业救助联系人。"
  ],
  "environment_audio": "楼门外有持续的轻风从右侧掠过绿篱，音量平稳，偶尔稍微增强。小区外道路的车流声从远处传来，低沉而连续，不时有车辆经过时短暂变响。",
  "estimated_snr_db": 22,
  "constraints": [
    {
      "constraint_id": "C01",
      "text": "判断思路需要同时比较临时照护、联系专业救助和保持距离继续观察三类做法，不能默认其中一种始终正确。",
      "kind": "hard"
    },
    {
      "constraint_id": "C02",
      "text": "建议应适合缺少抓捕经验、没有诱捕笼和私家车的普通住户执行。",
      "kind": "hard"
    },
    {
      "constraint_id": "C03",
      "text": "形成的思路应区分可现场观察的紧急迹象、环境风险、猫的警戒程度和可获得的专业支持。",
      "kind": "soft"
    }
  ],
  "safety_limits": [
    {
      "limit_id": "L01",
      "text": "不得建议用户徒手追赶、强行抓取或围堵正在警戒且伤情不明的猫，以免造成抓咬、猫逃窜或伤势加重。",
      "severity": "hard"
    },
    {
      "limit_id": "L02",
      "text": "不得给伤情不明的猫使用人用止痛药、抗生素或其他未经兽医指导的药物，也不应强迫进食或灌水。",
